import { DomainError } from "../domain/DomainError";
import { ProjectRepository } from "../domain/ProjectRepository";
import { Task } from "../domain/Task";
import { TaskRepository } from "../domain/TaskRepository";
import { parseTaskStatus } from "../domain/TaskStatus";
import { TaskDto, toTaskDto } from "./dto";
import { IdGenerator } from "./IdGenerator";

export interface AddTaskInput {
  projectId: string;
  title: string;
  description: string;
  dueDate?: string | null;
  status?: string;
}

export class AddTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: AddTaskInput): Promise<TaskDto> {
    const project = await this.projects.findById(input.projectId);
    if (project === undefined) {
      throw DomainError.notFound(`project ${input.projectId} not found`);
    }
    const task = Task.create({
      id: this.ids.next(),
      projectId: project.id,
      title: input.title,
      description: input.description,
      dueDate: parseDueDate(input.dueDate),
      status: input.status === undefined ? "todo" : parseTaskStatus(input.status),
    });
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

function parseDueDate(value: string | null | undefined): Date | null {
  if (value === undefined || value === null) {
    return null;
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw DomainError.validation("dueDate must be a valid date");
  }
  return date;
}

