import { DomainError } from "../domain/DomainError";
import { TaskRepository } from "../domain/TaskRepository";
import { UserRepository } from "../domain/UserRepository";
import { TaskDto, toTaskDto } from "./dto";
import { TaskFinderService } from "./TaskFinderService";

export interface AssignTaskInput {
  projectId: string;
  taskId: string;
  assigneeId: string;
}

export class AssignTaskUseCase {
  constructor(
    private readonly finder: TaskFinderService,
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  async execute(input: AssignTaskInput): Promise<TaskDto> {
    const task = await this.finder.findInProject(input.projectId, input.taskId);
    const user = await this.users.findById(input.assigneeId);
    if (user === undefined) {
      throw DomainError.notFound(`user ${input.assigneeId} not found`);
    }
    task.assignTo(user.id);
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

