import { DomainError } from "../domain/DomainError";
import { ProjectRepository } from "../domain/ProjectRepository";
import { TaskFilter, TaskRepository } from "../domain/TaskRepository";
import { parseTaskStatus } from "../domain/TaskStatus";
import { TaskDto, toTaskDto } from "./dto";

export interface ListTasksInput {
  projectId: string;
  status?: string;
  assigneeId?: string;
}

export class ListTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListTasksInput): Promise<TaskDto[]> {
    const project = await this.projects.findById(input.projectId);
    if (project === undefined) {
      throw DomainError.notFound(`project ${input.projectId} not found`);
    }
    const filter: TaskFilter = {};
    if (input.status !== undefined) {
      filter.status = parseTaskStatus(input.status);
    }
    if (input.assigneeId !== undefined) {
      filter.assigneeId = input.assigneeId;
    }
    const found = await this.tasks.findByProject(project.id, filter);
    return found.map(toTaskDto);
  }
}

